{
  "name": "NZ GPT",
  "description": "روبوت محادثة ذكي متقدم يدعم تحليل الصور وكتابة الأكواد البرمجية."
}

export enum Role {
  USER = 'user',
  MODEL = 'model'
}

export interface Message {
  id: string;
  role: Role;
  text: string;
  image?: string; // Base64 string for display
  timestamp: number;
}

export interface ChatSession {
  id: string;
  messages: Message[];
}

import { GoogleGenAI } from "@google/genai";
import { Message, Role } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
أنت NZ GPT، مساعد ذكاء اصطناعي ذكي ومفيد.
تم برمجتك وتصميمك لمساعدة المستخدمين في كتابة الأكواد البرمجية، تحليل الصور، والإجابة على الأسئلة العامة.
- إجاباتك دقيقة ومختصرة ومفيدة.
- عندما يطلب المستخدم كودًا، قدم كودًا نظيفًا وكاملاً واحترافيًا.
- لا تذكر أنك مرتبط بشركة جوجل أو أي شركات أخرى. أنت NZ GPT فقط.
- تحدث باللغة العربية بشكل افتراضي إلا إذا حدثك المستخدم بلغة أخرى.
`;

export const sendMessageToNZGPT = async (
  history: Message[],
  currentText: string,
  currentImageBase64?: string
): Promise<string> => {
  try {
    const model = "gemini-3-flash-preview";

    // Transform history for the API
    // We filter out image data from history to keep context lightweight, 
    // sending only text history + current multimodal input
    const historyParts = history.map(msg => ({
      role: msg.role === Role.USER ? 'user' : 'model',
      parts: [{ text: msg.text }]
    }));

    const parts: any[] = [];

    // Add image if exists
    if (currentImageBase64) {
      // Remove data:image/...;base64, prefix
      const base64Data = currentImageBase64.split(',')[1];
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg', // Assuming jpeg/png for simplicity, API handles most
          data: base64Data
        }
      });
    }

    // Add text prompt
    parts.push({ text: currentText });

    // Since specific chat history with mixed modalities can be tricky with the SDK helper,
    // we will use generateContent with the full context manually constructed or just the current turn
    // if we want to be stateless, but for a chat app, we want context.
    // However, specifically for multimodal history, it's safer to send the current turn with system instruction 
    // and let the model handle the immediate context or approximate history.

    // For this implementation, to ensure high quality code generation and image analysis, 
    // we will focus on the current prompt with system instructions. 
    // Note: To support full chat history with images via the SDK requires careful structure.
    // We will append previous text conversation to the current prompt to simulate memory if needed,
    // or use the 'contents' array properly.

    const contents = [
      ...historyParts,
      {
        role: 'user',
        parts: parts
      }
    ];

    const response = await ai.models.generateContent({
      model: model,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
      }
    });

    return response.text || "عذراً، لم أستطع معالجة طلبك في الوقت الحالي.";

  } catch (error) {
    console.error("Error communicating with NZ GPT:", error);
    return "حدث خطأ غير متوقع. يرجى المحاولة مرة أخرى.";
  }
};

import React, { useState } from 'react';
import { Check, Copy } from 'lucide-react';

interface CodeBlockProps {
  code: string;
  language?: string;
}

const CodeBlock: React.FC<CodeBlockProps> = ({ code, language = 'javascript' }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    await navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="my-4 rounded-lg overflow-hidden bg-[#1e1e1e] border border-gray-700 shadow-lg dir-ltr">
      <div className="flex items-center justify-between px-4 py-2 bg-[#2d2d2d] border-b border-gray-700">
        <span className="text-xs text-gray-400 font-mono uppercase">{language}</span>
        <button
          onClick={handleCopy}
          className="flex items-center gap-1 text-xs text-gray-400 hover:text-white transition-colors"
        >
          {copied ? <Check size={14} className="text-green-500" /> : <Copy size={14} />}
          <span>{copied ? 'تم النسخ' : 'نسخ الكود'}</span>
        </button>
      </div>
      <pre className="p-4 overflow-x-auto text-sm font-mono text-gray-300 leading-relaxed whitespace-pre-wrap dir-ltr text-left">
        <code>{code}</code>
      </pre>
    </div>
  );
};

export default CodeBlock;

import React from 'react';
import { Message, Role } from '../types';
import { User, Bot } from 'lucide-react';
import CodeBlock from './CodeBlock';

interface MessageItemProps {
  message: Message;
}

const MessageItem: React.FC<MessageItemProps> = ({ message }) => {
  const isUser = message.role === Role.USER;

  // Simple parser to detect code blocks ```code```
  const renderContent = (text: string) => {
    const parts = text.split(/(```[\s\S]*?```)/g);

    return parts.map((part, index) => {
      if (part.startsWith('```') && part.endsWith('```')) {
        // Extract content and optional language
        const content = part.slice(3, -3);
        const firstLineBreak = content.indexOf('\n');
        let language = 'code';
        let code = content;

        if (firstLineBreak > -1) {
            const potentialLang = content.substring(0, firstLineBreak).trim();
            // If the first line is short and looks like a language name
            if (potentialLang.length < 15 && !potentialLang.includes(' ')) {
                language = potentialLang || 'code';
                code = content.substring(firstLineBreak + 1);
            }
        }

        return <CodeBlock key={index} code={code.trim()} language={language} />;
      }

      // Render regular text with line breaks
      return (
        <p key={index} className="whitespace-pre-wrap mb-2 last:mb-0 leading-relaxed">
          {part}
        </p>
      );
    });
  };

  return (
    <div className={`flex w-full mb-6 ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex max-w-[90%] md:max-w-[80%] gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center ${
          isUser ? 'bg-indigo-600' : 'bg-emerald-600'
        } shadow-md`}>
          {isUser ? <User size={20} className="text-white" /> : <Bot size={20} className="text-white" />}
        </div>

        {/* Bubble */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
          <div className={`px-5 py-4 rounded-2xl shadow-sm text-[15px] ${
            isUser 
              ? 'bg-indigo-600 text-white rounded-tr-none' 
              : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
          }`}>

            {/* Display Image if present */}
            {message.image && (
              <div className="mb-4 rounded-lg overflow-hidden border border-white/20 max-w-sm">
                <img src={message.image} alt="User upload" className="w-full h-auto object-cover" />
              </div>
            )}

            {/* Text Content */}
            <div className={isUser ? 'text-indigo-50' : 'text-gray-800'}>
              {renderContent(message.text)}
            </div>
          </div>
          <span className="text-xs text-gray-400 mt-1 px-1">
            {isUser ? 'أنت' : 'NZ GPT'}
          </span>
        </div>
      </div>
    </div>
  );
};

export default MessageItem;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Trash2, Cpu } from 'lucide-react';
import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

function App() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: Role.MODEL,
      text: 'أهلاً بك في **NZ GPT**. كيف يمكنني مساعدتك اليوم؟ يمكنك سؤالي عن الأكواد البرمجية أو إرسال صور لتحليلها.',
      timestamp: Date.now()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleClearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleSendMessage = async () => {
    if ((!inputText.trim() && !selectedImage) || isLoading) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: inputText,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    // Update UI immediately
    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    setIsLoading(true);

    try {
      // Pass the *previous* messages as history, plus the new one logic is handled in service
      const responseText = await sendMessageToNZGPT(messages, newMessage.text, tempImage || undefined);

      const botMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: Role.MODEL,
        text: responseText,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, botMessage]);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const clearChat = () => {
    setMessages([]);
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 font-sans" dir="rtl">

      {/* Header */}
      <header className="bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between sticky top-0 z-10 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-indigo-200 shadow-lg">
            <Cpu className="text-white" size={24} />
          </div>
          <div>
            <h1 className="text-xl font-bold text-gray-800 tracking-tight">NZ GPT</h1>
            <p className="text-xs text-green-600 font-medium flex items-center gap-1">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
              متصل الآن
            </p>
          </div>
        </div>
        <button 
          onClick={clearChat}
          className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
          title="مسح المحادثة"
        >
          <Trash2 size={20} />
        </button>
      </header>

      {/* Chat Area */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6 bg-slate-50 scroll-smooth">
        <div className="max-w-4xl mx-auto">
          {messages.length === 0 && (
            <div className="flex flex-col items-center justify-center h-[50vh] text-center text-gray-400">
               <Cpu size={64} className="mb-4 text-gray-300" />
               <p>ابدأ المحادثة الآن مع NZ GPT</p>
            </div>
          )}
          {messages.map((msg) => (
            <MessageItem key={msg.id} message={msg} />
          ))}

          {isLoading && (
            <div className="flex w-full mb-6 justify-start animate-pulse">
              <div className="flex max-w-[80%] gap-3 flex-row">
                 <div className="w-10 h-10 rounded-full bg-emerald-600 flex items-center justify-center">
                    <Cpu size={20} className="text-white animate-spin" />
                 </div>
                 <div className="px-5 py-4 rounded-2xl bg-white text-gray-500 rounded-tr-none border border-gray-100 flex items-center gap-2">
                    <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></span>
                    <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-75"></span>
                    <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-150"></span>
                 </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </main>

      {/* Input Area */}
      <footer className="bg-white border-t border-gray-200 p-4 sticky bottom-0 z-20">
        <div className="max-w-4xl mx-auto">
          {/* Image Preview */}
          {selectedImage && (
            <div className="relative inline-block mb-3 animate-in fade-in slide-in-from-bottom-2">
              <img src={selectedImage} alt="Preview" className="h-20 w-20 object-cover rounded-xl border border-indigo-100 shadow-sm" />
              <button
                onClick={handleClearImage}
                className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 shadow-md hover:bg-red-600 transition-colors"
              >
                <X size={12} />
              </button>
            </div>
          )}

          <div className="flex items-end gap-2 bg-gray-50 p-2 rounded-2xl border border-gray-200 focus-within:border-indigo-400 focus-within:ring-4 focus-within:ring-indigo-50 transition-all">

            <button
              onClick={() => fileInputRef.current?.click()}
              className="p-3 text-gray-500 hover:text-indigo-600 hover:bg-white rounded-xl transition-colors"
              title="إرفاق صورة"
            >
              <ImageIcon size={24} />
            </button>
            <input
              type="file"
              ref={fileInputRef}
              accept="image/*"
              className="hidden"
              onChange={handleImageUpload}
            />

            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder="اكتب رسالتك هنا... (يمكنك طلب كود برمجي أو إرسال صورة)"
              className="flex-1 bg-transparent border-none focus:ring-0 resize-none py-3 px-2 max-h-32 min-h-[48px] text-gray-700 placeholder-gray-400"
              rows={1}
              style={{ overflow: 'hidden', height: 'auto' }}
              onInput={(e) => {
                const target = e.target as HTMLTextAreaElement;
                target.style.height = 'auto';
                target.style.height = `${Math.min(target.scrollHeight, 128)}px`;
              }}
            />

            <button
              onClick={handleSendMessage}
              disabled={(!inputText.trim() && !selectedImage) || isLoading}
              className={`p-3 rounded-xl flex items-center justify-center transition-all duration-200 ${
                (!inputText.trim() && !selectedImage) || isLoading
                  ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                  : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-md transform hover:scale-105 active:scale-95'
              }`}
            >
              <Send size={20} className={isLoading ? 'opacity-0' : 'opacity-100'} />
              {isLoading && <div className="absolute w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
            </button>
          </div>
          <div className="text-center mt-2">
            <p className="text-[10px] text-gray-400">NZ GPT can make mistakes. Consider checking important information.</p>
          </div>
        </div>
      </footer>
    </div>
  );
}

export default App;

