import { GoogleGenAI } from "@google/genai";
import { Message, Role } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
أنت NZ GPT، نظام ذكاء اصطناعي خاص ومتقدم.
تم تطويرك لتقديم حلول ذكية وشاملة.

المهام الأساسية:
1. **كتابة الأكواد البرمجية**: أنت مبرمج خبير. قدم أكواداً كاملة، نظيفة، وقابلة للعمل. إذا طلب المستخدم مشروعاً أو كوداً طويلاً، قم بكتابته بالكامل وتجزئته بشكل منطقي إذا لزم الأمر، لكن لا تختصر الحلول.
2. **تحليل الصور**: لديك قدرة عالية على فهم الصور وتحليل محتواها بدقة.
3. **المحادثة**: أسلوبك احترافي، مباشر، وداعم.

تعليمات الهوية (صارمة جداً):
- اسمك هو **NZ GPT** فقط.
- لا تذكر مطلقاً أنك نموذج من Google أو Gemini أو أي شركة أخرى.
- لا تذكر تفاصيل تقنية عن خوادم المعالجة.
- تعامل مع المستخدم على أنك نظام خاص "بيننا".
- لغتك الأساسية هي العربية، مع استخدام الإنجليزية للمصطلحات التقنية.
`;

export const sendMessageToNZGPT = async (
  history: Message[],
  currentText: string,
  currentImageBase64?: string
): Promise<string> => {
  try {
    // Using gemini-3-pro-preview for superior coding and reasoning capabilities
    const model = "gemini-3-pro-preview";

    // Transform history for the API
    const historyParts = history.map(msg => ({
      role: msg.role === Role.USER ? 'user' : 'model',
      parts: [{ text: msg.text }]
    }));

    const parts: any[] = [];

    // Add image if exists
    if (currentImageBase64) {
      const base64Data = currentImageBase64.split(',')[1];
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: base64Data
        }
      });
    }

    parts.push({ text: currentText });

    const contents = [
      ...historyParts,
      {
        role: 'user',
        parts: parts
      }
    ];

    const response = await ai.models.generateContent({
      model: model,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        // Ensure enough tokens for large code generation
        // Thinking budget can help with complex coding tasks
        thinkingConfig: { thinkingBudget: 2048 }, 
        maxOutputTokens: 8192, 
      }
    });

    return response.text || "عذراً، لم أستطع معالجة طلبك.";

  } catch (error) {
    console.error("Error communicating with NZ GPT:", error);
    return "حدث خطأ في الاتصال. يرجى المحاولة مجدداً.";
  }
};

