import { GoogleGenAI } from "@google/genai";
import { Message, Role } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
أنت NZ GPT، نظام ذكاء اصطناعي خاص ومتقدم.
مهمتك هي مساعدة المستخدم في كتابة الأكواد البرمجية، تحليل الصور، والإجابة على الأسئلة.

القواعد الصارمة:
1. **الهوية**: أنت "NZ GPT" فقط. لا تذكر جوجل (Google) أو جيميناي (Gemini) أو أي شركة أخرى مطلقاً. أنت نظام مستقل خاص.
2. **البرمجة**: عندما يطلب المستخدم كوداً، قدم حلاً برمجياً كاملاً واحترافياً ونظيفاً. لا تختصر الأكواد.
3. **الصور**: قم بتحليل الصور بدقة عالية إذا تم إرسالها.
4. **الخصوصية**: لا تخبر المستخدم كيف تتم معالجة بياناته، فقط قدم له الإجابة.
5. **اللغة**: تحدث بالعربية كلغة أساسية، واستخدم الإنجليزية للمصطلحات التقنية والأكواد.
`;

export const sendMessageToNZGPT = async (
  history: Message[],
  currentText: string,
  currentImageBase64?: string
): Promise<string> => {
  try {
    const model = "gemini-3-pro-preview";

    // API Requirement: Conversation must start with a User message.
    // We filter out any leading Model messages (like the welcome message).
    const firstUserIndex = history.findIndex(msg => msg.role === Role.USER);
    const effectiveHistory = firstUserIndex >= 0 ? history.slice(firstUserIndex) : [];

    const historyParts = effectiveHistory.map(msg => ({
      role: msg.role === Role.USER ? 'user' : 'model',
      parts: [{ text: msg.text }]
    }));

    const parts: any[] = [];

    // Add image if exists
    if (currentImageBase64) {
      const base64Data = currentImageBase64.split(',')[1];
      parts.push({
        inlineData: {
          mimeType: 'image/jpeg',
          data: base64Data
        }
      });
    }

    parts.push({ text: currentText });

    const contents = [
      ...historyParts,
      {
        role: 'user',
        parts: parts
      }
    ];

    const response = await ai.models.generateContent({
      model: model,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        thinkingConfig: { thinkingBudget: 2048 }, 
        maxOutputTokens: 8192, 
      }
    });

    return response.text || "عذراً، لم أستطع معالجة طلبك.";

  } catch (error) {
    console.error("Error communicating with NZ GPT:", error);
    return "حدث خطأ في الاتصال. يرجى التأكد من اتصالك بالإنترنت والمحاولة مجدداً.";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Trash2, Sparkles, Terminal } from 'lucide-react';
import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

function App() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: Role.MODEL,
      text: 'أهلاً بك في **NZ GPT**. \nأنا هنا لمساعدتك في كتابة الأكواد البرمجية، تحليل الصور، وحل المشكلات التقنية. كيف يمكنني خدمتك؟',
      timestamp: Date.now()
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleClearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleSendMessage = async () => {
    if ((!inputText.trim() && !selectedImage) || isLoading) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: inputText,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    setIsLoading(true);

    try {
      const responseText = await sendMessageToNZGPT(messages, newMessage.text, tempImage || undefined);

      const botMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: Role.MODEL,
        text: responseText,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, botMessage]);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const clearChat = () => {
    setMessages([]);
  };

  return (
    <div className="flex flex-col h-screen bg-slate-50 font-sans text-slate-900" dir="rtl">

      {/* Header */}
      <header className="bg-white/90 backdrop-blur-sm border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-10 shadow-sm">
        <div className="flex items-center gap-3">
