            <span className="text-white font-bold font-mono tracking-tighter">NZ</span>
          </div>
          <div>
            <h1 className="text-lg font-bold text-slate-800 tracking-tight">NZ GPT</h1>
          </div>
        </div>
        <button 
          onClick={clearChat}
          className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
          title="بدء محادثة جديدة"
        >
          <Trash2 size={18} />
        </button>
      </header>

      {/* Chat Area */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6 bg-slate-50 scroll-smooth">
        <div className="max-w-4xl mx-auto space-y-6">
          {messages.length === 0 && (
            <div className="flex flex-col items-center justify-center h-[60vh] text-center text-slate-400 opacity-0 animate-in fade-in duration-700">
               <div className="w-16 h-16 bg-white rounded-2xl shadow-sm border border-slate-100 flex items-center justify-center mb-4">
                  <Terminal size={32} className="text-slate-300" />
               </div>
