    setSelectedImage(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    textareaRef.current?.focus();
  };

  const handleSendMessage = async (textOverride?: string) => {
    const textToSend = textOverride || inputText;

    if ((!textToSend.trim() && !selectedImage) || isLoading) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';

    // Reset textarea height
    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.focus();
    }

    setIsLoading(true);

    try {
      const responseText = await sendMessageToNZGPT(messages, newMessage.text, tempImage || undefined);

      const botMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: Role.MODEL,
        text: responseText,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, botMessage]);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
      // Ensure focus is back after loading
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const clearChat = () => {
    setMessages([]);
    textareaRef.current?.focus();
  };

  // Suggestions for empty state
  const suggestions = [
    { icon: <Code size={20} />, text: "كتابة كود React و Node.js", prompt: "أريد كتابة تطبيق كامل باستخدام React و Node.js يرجى تزويدي بالهيكل والأكواد الأساسية." },
    { icon: <Bug size={20} />, text: "اكتشاف الأخطاء في الكود", prompt: "لدي كود لا يعمل كما هو متوقع، هل يمكنك مساعدتي في فحصه واكتشاف الأخطاء؟" },
    { icon: <Cpu size={20} />, text: "شرح خوارزمية معقدة", prompt: "اشرح لي كيف تعمل خوارزميات التعلم العميق (Deep Learning) ببساطة." },
    { icon: <Layers size={20} />, text: "تحليل بنية قاعدة بيانات", prompt: "ما هي أفضل هيكلية لقاعدة بيانات تطبيق تجارة إلكترونية؟" },
  ];

  return (
    <div className="flex flex-col h-screen bg-slate-50 font-sans text-slate-900" dir="rtl">

      {/* Header */}
      <header className="bg-white/90 backdrop-blur-sm border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-10 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-slate-900 rounded-lg flex items-center justify-center shadow-md">
            <span className="text-white font-bold font-mono tracking-tighter">NZ</span>
          </div>
          <div>
            <h1 className="text-lg font-bold text-slate-800 tracking-tight">NZ GPT</h1>
            <div className="flex items-center gap-1.5 opacity-60">
               <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
               <span className="text-[10px] font-medium">متصل</span>
            </div>
          </div>
        </div>
        <button 
          onClick={clearChat}
          className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
          title="بدء محادثة جديدة"
        >
          <Trash2 size={18} />
        </button>
      </header>

      {/* Chat Area */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6 bg-slate-50 scroll-smooth">
        <div className="max-w-4xl mx-auto space-y-6">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full min-h-[50vh] animate-in fade-in duration-700">
               <div className="w-20 h-20 bg-white rounded-3xl shadow-sm border border-slate-100 flex items-center justify-center mb-6">
                  <Terminal size={40} className="text-slate-800" />
               </div>
               <h2 className="text-2xl font-bold text-slate-800 mb-2">مرحباً بك في NZ GPT</h2>
               <p className="text-slate-500 mb-10 text-center max-w-md">
                 نظام الذكاء الاصطناعي المتقدم للمطورين. يمكنني كتابة الأكواد، تحليل الصور، وحل المشكلات المعقدة.
               </p>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-2xl px-4">
                 {suggestions.map((item, idx) => (
                   <button 
                    key={idx}
                    onClick={() => handleSendMessage(item.prompt)}
                    className="flex items-center gap-4 p-4 bg-white border border-slate-200 rounded-xl hover:border-slate-400 hover:shadow-md transition-all text-right group"
                   >
                     <div className="p-2 bg-slate-50 rounded-lg text-slate-600 group-hover:bg-slate-100 group-hover:text-slate-900 transition-colors">
                       {item.icon}
                     </div>
                     <span className="text-sm font-medium text-slate-700 group-hover:text-slate-900">{item.text}</span>
                   </button>
                 ))}
               </div>
            </div>
          ) : (
            <>
              {messages.map((msg) => (
                <MessageItem key={msg.id} message={msg} />
              ))}
            </>
          )}

          {isLoading && (
            <div className="flex w-full mb-6 justify-start">
              <div className="flex max-w-[80%] gap-3 flex-row">
                 <div className="flex-shrink-0 w-9 h-9 bg-slate-900 rounded-lg flex items-center justify-center shadow-sm animate-pulse">
                    <span className="text-white font-bold font-mono text-xs">NZ</span>
                 </div>
                 <div className="px-5 py-4 rounded-2xl bg-white rounded-tl-none border border-slate-200 flex items-center gap-2 shadow-sm">
                    <span className="w-2 h-2 bg-slate-300 rounded-full animate-bounce"></span>
                    <span className="w-2 h-2 bg-slate-300 rounded-full animate-bounce delay-75"></span>
                    <span className="w-2 h-2 bg-slate-300 rounded-full animate-bounce delay-150"></span>
                 </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </main>

      {/* Input Area */}
      <footer className="bg-white border-t border-slate-100 p-4 sticky bottom-0 z-20">
        <div className="max-w-4xl mx-auto">
          {/* Image Preview */}
          {selectedImage && (
            <div className="relative inline-block mb-3 animate-in slide-in-from-bottom-2 fade-in">
              <div className="relative rounded-lg overflow-hidden border border-slate-200 shadow-sm group">
                <img src={selectedImage} alt="Preview" className="h-20 w-auto object-cover" />
                <button
                  onClick={handleClearImage}
                  className="absolute top-1 right-1 bg-black/50 hover:bg-black/70 text-white rounded-full p-1 transition-colors"
                >
                  <X size={12} />
                </button>
              </div>
            </div>
          )}

          <div className="flex items-end gap-2 bg-slate-50 p-2 rounded-xl border border-slate-200 focus-within:border-slate-400 focus-within:ring-2 focus-within:ring-slate-100 transition-all shadow-inner">

            <button
              onClick={() => fileInputRef.current?.click()}
              className="p-3 text-slate-400 hover:text-slate-800 hover:bg-white rounded-lg transition-colors"
              title="إرفاق صورة"
            >
              <ImageIcon size={20} />
            </button>
            <input
              type="file"
              ref={fileInputRef}
              accept="image/*"
              className="hidden"
              onChange={handleImageUpload}
            />

            <textarea
              ref={textareaRef}
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder="اكتب رسالتك..."
              className="flex-1 bg-transparent border-none focus:ring-0 resize-none py-3 px-2 max-h-60 min-h-[44px] text-slate-800 placeholder-slate-400 leading-relaxed font-medium"
              rows={1}
              style={{ overflow: 'hidden', height: 'auto' }}
              onInput={(e) => {
                const target = e.target as HTMLTextAreaElement;
                target.style.height = 'auto';
                target.style.height = `${Math.min(target.scrollHeight, 240)}px`;
              }}
            />

            <button
              onClick={() => handleSendMessage()}
              disabled={(!inputText.trim() && !selectedImage) || isLoading}
              className={`p-3 rounded-lg flex items-center justify-center transition-all duration-200 ${
                (!inputText.trim() && !selectedImage) || isLoading
                  ? 'bg-slate-200 text-slate-400 cursor-not-allowed'
                  : 'bg-slate-900 text-white hover:bg-black shadow-md hover:shadow-lg active:scale-95'
              }`}
            >
              <Send size={18} className={isLoading ? 'opacity-0' : 'opacity-100'} />
              {isLoading && <div className="absolute w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
            </button>
          </div>
        </div>
      </footer>
    </div>
  );
}

export default App;

import React from 'react';
import { Message, Role } from '../types';
import { User } from 'lucide-react';
import CodeBlock from './CodeBlock';

interface MessageItemProps {
  message: Message;
}

const MessageItem: React.FC<MessageItemProps> = ({ message }) => {
  const isUser = message.role === Role.USER;

  // Function to render text with Bold and Inline Code formatting
  const renderFormattedText = (text: string) => {
    // Split by bold (**...**) and inline code (`...`)
    const parts = text.split(/(\*\*.*?\*\*|`.*?`)/g);

    return parts.map((part, index) => {
      if (part.startsWith('`') && part.endsWith('`')) {
        return (
          <code key={index} className="bg-slate-200 text-slate-800 px-1.5 py-0.5 rounded text-sm font-mono mx-0.5" dir="ltr">
            {part.slice(1, -1)}
          </code>
        );
      }
      if (part.startsWith('**') && part.endsWith('**')) {
        return (
          <strong key={index} className="font-bold text-slate-900">
            {part.slice(2, -2)}
          </strong>
        );
      }
      return part;
    });
  };

  // Main parser to separate big Code Blocks ```...``` from regular text
  const renderContent = (text: string) => {
    const parts = text.split(/(```[\s\S]*?```)/g);

    return parts.map((part, index) => {
      if (part.startsWith('```') && part.endsWith('```')) {
        // Extract content and optional language
        const content = part.slice(3, -3);
        const firstLineBreak = content.indexOf('\n');
        let language = 'code';
        let code = content;

        if (firstLineBreak > -1) {
            const potentialLang = content.substring(0, firstLineBreak).trim();
            // If the first line is short and looks like a language name
            if (potentialLang.length < 15 && !potentialLang.includes(' ')) {
                language = potentialLang || 'code';
                code = content.substring(firstLineBreak + 1);
            }
        }

        return <CodeBlock key={index} code={code.trim()} language={language} />;
      }

      // Render regular text paragraphs
      if (part.trim() === '') return null;

      return (
        <div key={index} className="whitespace-pre-wrap mb-3 last:mb-0 leading-relaxed text-[15px]">
          {renderFormattedText(part)}
        </div>
      );
    });
  };

  return (
    <div className={`flex w-full mb-6 ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex max-w-[90%] md:max-w-[85%] gap-3 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-9 h-9 rounded-lg flex items-center justify-center ${
          isUser ? 'bg-slate-700' : 'bg-slate-900'
        } shadow-sm mt-1`}>
          {isUser ? <User size={18} className="text-white" /> : <span className="text-white font-bold font-mono text-xs">NZ</span>}
        </div>

        {/* Bubble */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} min-w-0`}>
          <div className={`px-5 py-3.5 rounded-2xl shadow-sm text-[15px] break-words w-full ${
            isUser 
              ? 'bg-slate-800 text-white rounded-tr-none' 
              : 'bg-white text-slate-800 rounded-tl-none border border-slate-200'
          }`}>

            {/* Display Image if present */}
            {message.image && (
              <div className="mb-4 rounded-lg overflow-hidden border border-white/20 max-w-sm">
                <img src={message.image} alt="User upload" className="w-full h-auto object-cover" />
              </div>
            )}

            {/* Text Content */}
            <div className={isUser ? 'text-slate-100' : 'text-slate-800'}>
              {renderContent(message.text)}
            </div>
          </div>
          <span className="text-[10px] text-slate-400 mt-1 px-1 opacity-70 select-none">
            {isUser ? 'أنت' : 'NZ GPT'}
          </span>
        </div>
      </div>
    </div>
  );
};

