    await navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="my-5 rounded-xl overflow-hidden bg-slate-950 border border-slate-800 shadow-2xl dir-ltr text-left group">
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2.5 bg-slate-900 border-b border-slate-800">
        <div className="flex items-center gap-3">
          <div className="flex gap-1.5">
            <div className="w-2.5 h-2.5 rounded-full bg-red-500/80"></div>
            <div className="w-2.5 h-2.5 rounded-full bg-amber-500/80"></div>
            <div className="w-2.5 h-2.5 rounded-full bg-emerald-500/80"></div>
          </div>
          <span className="text-xs text-slate-400 font-mono font-medium lowercase flex items-center gap-1.5 opacity-80">
            <Terminal size={10} strokeWidth={3} />
            {language}
          </span>
        </div>

        <button
          onClick={handleCopy}
          className={`flex items-center gap-1.5 text-[10px] font-medium px-2 py-1 rounded-md transition-all duration-200 border ${
            copied 
              ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' 
              : 'bg-slate-800 text-slate-400 border-slate-700 hover:text-white hover:border-slate-600'
          }`}
        >
          {copied ? <Check size={12} strokeWidth={3} /> : <Copy size={12} />}
          <span className="uppercase tracking-wider">{copied ? 'COPIED' : 'COPY'}</span>
        </button>
      </div>

      {/* Content */}
      <div className="relative">
        <pre className="p-5 overflow-x-auto text-[13px] md:text-sm font-mono leading-7 text-slate-300 whitespace-pre-wrap font-medium">
          <code style={{ fontFamily: '"Fira Code", monospace' }}>{code}</code>
        </pre>
      </div>
    </div>
  );
};

