import { GoogleGenAI } from "@google/genai";
import { Message, Role } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
أنت **NZ GPT**، نظام ذكاء اصطناعي خاص، فائق التطور، وموجه للمطورين والمحترفين.

**القواعد الأساسية الصارمة (Top Secret):**
1. **هويتك**: اسمك هو "NZ GPT" فقط.
2. **السرية**: يُمنع منعاً باتاً ذكر "Google" أو "Gemini" أو "DeepMind" أو أي جهة أخرى. أنت نظام مستقل تماماً.
3. **مهمتك**: 
   - كتابة أكواد برمجية معقدة وكاملة (Full Stack).
   - تحليل الصور الهندسية والبرمجية بدقة.
   - حل المشاكل التقنية (Debugging).
4. **الأسلوب**:
   - كن مباشراً واحترافياً.
   - عند كتابة الكود، اكتبه كاملاً ولا تستخدم عبارات مثل "بقية الكود هنا".
   - استخدم تنسيق Markdown (Bold, Code Blocks) لتوضيح الشرح.
   - عند طلب كود، قدم الحل الأمثل والأكثر حداثة.

**اللغة**:
- اللغة العربية للشرح والتواصل.
- اللغة الإنجليزية للمصطلحات التقنية والأكواد.
`;

export const sendMessageToNZGPT = async (
  history: Message[],
  currentText: string,
  onTokenReceived: (fullText: string) => void,
  currentImageBase64?: string
): Promise<string> => {
  try {
    // gemini-3-pro-preview is best for reasoning and coding
    const model = "gemini-3-pro-preview";

    // API Requirement: Conversation must start with a User message.
    const firstUserIndex = history.findIndex(msg => msg.role === Role.USER);
    const effectiveHistory = firstUserIndex >= 0 ? history.slice(firstUserIndex) : [];

    const historyParts = effectiveHistory.map(msg => {
      const parts: any[] = [];

      if (msg.role === Role.USER && msg.image) {
        const matches = msg.image.match(/^data:(.+);base64,(.+)$/);
        if (matches) {
          parts.push({
            inlineData: {
              mimeType: matches[1],
              data: matches[2]
            }
          });
        }
      }

      if (msg.text) {
        parts.push({ text: msg.text });
      }

      return {
        role: msg.role === Role.USER ? 'user' : 'model',
        parts: parts
      };
    });

    const parts: any[] = [];

    if (currentImageBase64) {
      const matches = currentImageBase64.match(/^data:(.+);base64,(.+)$/);
      if (matches) {
        parts.push({
          inlineData: {
            mimeType: matches[1],
            data: matches[2]
          }
        });
      }
    }

    parts.push({ text: currentText });

    const contents = [
      ...historyParts,
      {
        role: 'user',
        parts: parts
      }
    ];

    // Use generateContentStream for real-time typing effect
    const responseStream = await ai.models.generateContentStream({
      model: model,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        thinkingConfig: { thinkingBudget: 32768 }, // Absolute Max for complex code
        maxOutputTokens: 8192,
        temperature: 0.7, 
      }
    });

    let fullText = "";
    for await (const chunk of responseStream) {
      const text = chunk.text;
      if (text) {
        fullText += text;
        onTokenReceived(fullText);
      }
    }

    return fullText;

  } catch (error) {
    console.error("Error communicating with NZ GPT:", error);
    throw error;
  }
};

