import React from 'react';
import { Message, Role } from '../types';
import { User, ExternalLink } from 'lucide-react';
import CodeBlock from './CodeBlock';

interface MessageItemProps {
  message: Message;
}

const MessageItem: React.FC<MessageItemProps> = ({ message }) => {
  const isUser = message.role === Role.USER;

  // 1. Parser for Inline Styles (Bold, Code, Links)
  const renderInlineStyles = (text: string) => {
    const parts = text.split(/(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))/g);

    return parts.map((part, index) => {
      // Handle Inline Code
      if (part.startsWith('`') && part.endsWith('`')) {
        return (
          <code key={index} className="bg-slate-100 text-pink-600 px-1.5 py-0.5 rounded text-[13px] font-mono mx-0.5 border border-slate-200" dir="ltr">
            {part.slice(1, -1)}
          </code>
        );
      }
      // Handle Bold
      if (part.startsWith('**') && part.endsWith('**')) {
        return (
          <strong key={index} className="font-bold text-slate-900">
            {part.slice(2, -2)}
          </strong>
        );
      }
      // Handle Links
      if (part.startsWith('[') && part.includes('](') && part.endsWith(')')) {
        const match = part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
        if (match) {
          return (
            <a 
              key={index} 
              href={match[2]} 
              target="_blank" 
              rel="noopener noreferrer"
              className="text-blue-600 hover:text-blue-800 hover:underline inline-flex items-center gap-0.5 mx-1 font-medium transition-colors"
            >
              {match[1]}
              <ExternalLink size={10} strokeWidth={2.5} />
            </a>
          );
        }
      }
      return part;
    });
  };

  // 2. Parser for Block Elements
  const renderBlockElements = (textChunk: string) => {
    const lines = textChunk.split('\n');
    const elements: React.ReactNode[] = [];

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const trimmedLine = line.trim();

      if (!trimmedLine) {
        if (i > 0 && i < lines.length - 1) {
             elements.push(<div key={i} className="h-3"></div>);
        }
        continue;
      }

      // Heading 3 (###)
      if (trimmedLine.startsWith('### ')) {
        elements.push(
          <h3 key={i} className="text-lg font-bold text-slate-800 mt-4 mb-2 leading-tight">
            {renderInlineStyles(trimmedLine.replace(/^###\s+/, ''))}
          </h3>
        );
      }
      // Heading 2 (##)
      else if (trimmedLine.startsWith('## ')) {
        elements.push(
          <h2 key={i} className="text-xl font-bold text-slate-900 mt-6 mb-3 border-b border-slate-200 pb-2">
            {renderInlineStyles(trimmedLine.replace(/^##\s+/, ''))}
          </h2>
        );
      }
      // Heading 1 (#)
      else if (trimmedLine.startsWith('# ')) {
        elements.push(
          <h1 key={i} className="text-2xl font-bold text-slate-900 mt-6 mb-4 border-b border-slate-200 pb-2">
            {renderInlineStyles(trimmedLine.replace(/^#\s+/, ''))}
          </h1>
        );
      }
      // Unordered List (- or *)
      else if (trimmedLine.match(/^[\-\*]\s/)) {
        elements.push(
          <div key={i} className="flex items-start gap-2 mb-2 mr-1">
            <span className="text-slate-400 mt-2 text-[6px] flex-shrink-0">●</span>
            <span className="leading-relaxed text-slate-700">
              {renderInlineStyles(trimmedLine.replace(/^[\-\*]\s+/, ''))}
            </span>
          </div>
        );
      }
      // Ordered List (1.)
      else if (trimmedLine.match(/^\d+\.\s/)) {
         const numberMatch = trimmedLine.match(/^(\d+)\.\s/);
         const number = numberMatch ? numberMatch[1] : '1';
        elements.push(
          <div key={i} className="flex items-start gap-2 mb-2 mr-1">
            <span className="text-slate-500 font-bold text-sm flex-shrink-0 mt-0.5 min-w-[20px]">{number}.</span>
            <span className="leading-relaxed text-slate-700">
              {renderInlineStyles(trimmedLine.replace(/^\d+\.\s+/, ''))}
            </span>
          </div>
        );
      }
      // Blockquote (>)
      else if (trimmedLine.startsWith('> ')) {
          elements.push(
              <div key={i} className="border-r-4 border-slate-300 pr-4 py-1 my-2 text-slate-600 italic bg-slate-50 rounded-l-lg">
                  {renderInlineStyles(trimmedLine.replace(/^>\s+/, ''))}
              </div>
          )
      }
      // Regular Paragraph
      else {
        elements.push(
          <p key={i} className="mb-2 leading-7 text-slate-700 text-[15px]">
            {renderInlineStyles(line)}
          </p>
        );
      }
    }
    return elements;
  };

  // 3. Main Splitter (Code Blocks vs Text)
  // Updated regex to catch unclosed code blocks during streaming
  const renderContent = (fullText: string) => {
    const parts = fullText.split(/(```[\s\S]*?```|```[\s\S]*$)/g);

    return parts.map((part, index) => {
      // Handle Code Block (closed or unclosed)
      if (part.startsWith('```')) {
        let content = part.slice(3);
        if (content.endsWith('```')) {
            content = content.slice(0, -3);
        }

        const firstLineBreak = content.indexOf('\n');
        let language = 'code';
        let code = content;

        if (firstLineBreak > -1) {
            const potentialLang = content.substring(0, firstLineBreak).trim();
            if (potentialLang.length < 15 && !potentialLang.includes(' ')) {
                language = potentialLang || 'code';
                code = content.substring(firstLineBreak + 1);
            }
        }
        return <CodeBlock key={index} code={code.trim()} language={language} />;
      }

      // Handle Text Chunk
      if (part.trim() === '') return null;

      return (
        <div key={index} className="text-base">
          {renderBlockElements(part)}
        </div>
      );
    });
  };

  return (
    <div className={`flex w-full mb-8 animate-in slide-in-from-bottom-2 duration-500 ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex max-w-[95%] md:max-w-[85%] gap-4 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>

        {/* Avatar */}
        <div className={`flex-shrink-0 w-10 h-10 rounded-xl flex items-center justify-center ${
          isUser ? 'bg-slate-800' : 'bg-gradient-to-br from-slate-900 to-slate-700'
        } shadow-lg mt-1 ring-2 ring-white`}>
          {isUser ? <User size={20} className="text-white" /> : <span className="text-white font-bold font-mono text-sm">NZ</span>}
        </div>

        {/* Bubble */}
        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'} min-w-0 flex-1`}>
          <div className={`px-6 py-5 rounded-3xl shadow-sm text-[15px] break-words w-full ${
            isUser 
              ? 'bg-slate-800 text-white rounded-tr-sm shadow-md' 
              : 'bg-white text-slate-800 rounded-tl-sm border border-slate-100 shadow-sm'
          }`}>

            {/* Display Image if present */}
            {message.image && (
              <div className="mb-4 rounded-xl overflow-hidden border border-slate-200/20 max-w-sm shadow-sm">
                <img src={message.image} alt="User upload" className="w-full h-auto object-cover" />
              </div>
            )}

            {/* Text Content */}
            <div className={isUser ? 'text-slate-100' : ''}>
              {isUser ? (
                 <p className="whitespace-pre-wrap leading-relaxed text-[15px]">{message.text}</p>
              ) : (
                 renderContent(message.text)
              )}
            </div>
          </div>

          <span className="text-[11px] text-slate-400 mt-2 px-1 font-medium tracking-wide opacity-60 select-none">
            {isUser ? 'أنت' : 'NZ GPT'} • {new Date(message.timestamp).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
      </div>
    </div>
  );
};

