import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading, isStreaming]);

  useEffect(() => {
    textareaRef.current?.focus();
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const handleClearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    textareaRef.current?.focus();
  };

  const handleSendMessage = async (textOverride?: string) => {
    const textToSend = textOverride || inputText;

    if ((!textToSend.trim() && !selectedImage) || isLoading) return;

    // 1. Create User Message
    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);

    // Clear inputs
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';

    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.focus();
    }

    setIsLoading(true);

    try {
      // 2. Prepare Placeholder for Bot Message
      const botMsgId = (Date.now() + 100).toString();
      let isFirstChunk = true;

      await sendMessageToNZGPT(
        messages, 
        textToSend,
        (streamedText) => {
           if (isFirstChunk) {
             setIsLoading(false);
             setIsStreaming(true);
             // Create the message on first chunk
             setMessages(prev => [
               ...prev, 
               {
                 id: botMsgId,
                 role: Role.MODEL,
                 text: streamedText,
                 timestamp: Date.now()
               }
             ]);
             isFirstChunk = false;
           } else {
             // Update existing message
             setMessages(prev => prev.map(msg => 
               msg.id === botMsgId ? { ...msg, text: streamedText } : msg
             ));
           }
        },
        tempImage || undefined
      );

    } catch (error) {
      console.error(error);
      if (isLoading) {
          // If error happened before any streaming
          const errorMessage: Message = {
             id: (Date.now() + 200).toString(),
             role: Role.MODEL,
             text: "عذراً، واجهت مشكلة في الاتصال. يرجى المحاولة مرة أخرى.",
             timestamp: Date.now()
          };
          setMessages(prev => [...prev, errorMessage]);
      } else {
          // If error happened during streaming (unlikely but possible), append error note
          setMessages(prev => {
              const last = prev[prev.length - 1];
              if (last.role === Role.MODEL) {
                  return [...prev.slice(0, -1), { ...last, text: last.text + "\n\n[حدث خطأ في الشبكة]" }];
              }
              return prev;
          });
      }
    } finally {
      setIsLoading(false);
      setIsStreaming(false);
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const clearChat = () => {
    setMessages([]);
    setTimeout(() => textareaRef.current?.focus(), 100);
  };

  const suggestions = [
    { icon: <Code size={20} />, text: "تطبيق React كامل", prompt: "أريد كود لتطبيق To-Do List باستخدام React و Tailwind CSS مع شرح الهيكلية." },
    { icon: <Cpu size={20} />, text: "شرح Docker", prompt: "ما هو Docker وكيف أستخدمه لإنشاء بيئة تطوير لـ Node.js؟" },
    { icon: <Layers size={20} />, text: "تصميم قاعدة بيانات", prompt: "اقترح مخطط قاعدة بيانات SQL لنظام إدارة مدرسة (طلاب، معلمين، فصول)." },
    { icon: <Terminal size={20} />, text: "Bash Script", prompt: "اكتب Bash Script لعمل نسخة احتياطية للملفات يومياً." },
  ];

  return (
    <div className="flex flex-col h-screen bg-slate-50 font-sans text-slate-900 selection:bg-slate-800 selection:text-white overflow-hidden" dir="rtl">

      {/* Header */}
      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200/60 px-6 py-4 flex items-center justify-between sticky top-0 z-20 transition-all duration-300">
        <div className="flex items-center gap-3.5">
          <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center shadow-lg shadow-slate-900/20 ring-2 ring-white hover:scale-105 transition-transform duration-300">
            <span className="text-white font-bold font-mono tracking-tighter text-sm">NZ</span>
          </div>
          <div>
            <h1 className="text-xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
              NZ GPT 
              <span className="px-2 py-0.5 rounded-full bg-slate-100 text-slate-500 text-[10px] font-mono border border-slate-200">PRO</span>
            </h1>
            <div className="flex items-center gap-1.5 opacity-60">
               <div className={`w-1.5 h-1.5 rounded-full ${isLoading ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'} shadow-[0_0_8px_rgba(16,185,129,0.5)]`}></div>
               <span className="text-[11px] font-medium tracking-wide">
                 {isLoading ? 'جاري التفكير...' : (isStreaming ? 'جاري الكتابة...' : 'متصل وجاهز')}
               </span>
            </div>
          </div>
        </div>
        {messages.length > 0 && (
          <button 
            onClick={clearChat}
            disabled={isLoading || isStreaming}
            className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all duration-200 hover:shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
            title="مسح المحادثة"
          >
            <Trash2 size={18} />
          </button>
        )}
      </header>

      {/* Chat Area */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6 lg:p-8 bg-slate-50 scroll-smooth">
        <div className="max-w-4xl mx-auto space-y-6 pb-4 min-h-full flex flex-col">
          {messages.length === 0 ? (
            <div className="flex flex-col items-center justify-center flex-1 animate-in fade-in duration-700 slide-in-from-bottom-4 my-auto">
               <div className="w-24 h-24 bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100 flex items-center justify-center mb-8 relative group">
                  <div className="absolute inset-0 bg-gradient-to-tr from-slate-50 to-transparent rounded-[2rem]"></div>
                  <Terminal size={48} className="text-slate-800 relative z-10 group-hover:scale-110 transition-transform duration-300" strokeWidth={1.5} />
               </div>
               <h2 className="text-3xl font-bold text-slate-800 mb-3 tracking-tight">مرحباً بك في NZ GPT</h2>
               <p className="text-slate-500 mb-12 text-center max-w-md leading-relaxed">
                 مساعدك الذكي للمهام البرمجية المتقدمة. ابدأ بسؤال أو اختر من الاقتراحات أدناه.
               </p>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-3xl px-2">
                 {suggestions.map((item, idx) => (
                   <button 
                    key={idx}
                    onClick={() => handleSendMessage(item.prompt)}
                    className="flex items-center gap-4 p-4 bg-white border border-slate-200 rounded-2xl hover:border-slate-800/20 hover:shadow-lg hover:-translate-y-1 transition-all duration-300 text-right group relative overflow-hidden"
                   >
                     <div className="absolute inset-0 bg-slate-50 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></div>
                     <div className="p-2.5 bg-slate-50 rounded-xl text-slate-600 group-hover:bg-white group-hover:text-slate-900 transition-colors shadow-sm relative z-10">
                       {item.icon}
                     </div>
                     <span className="text-sm font-semibold text-slate-700 group-hover:text-slate-900 relative z-10">{item.text}</span>
                   </button>
                 ))}
               </div>
            </div>
          ) : (
            <>
              {messages.map((msg) => (
                <MessageItem key={msg.id} message={msg} />
              ))}
            </>
          )}

          {/* Enhanced Loading State - Only shows before first token arrives */}
          {isLoading && (
            <div className="flex w-full mb-8 justify-start animate-in fade-in duration-300">
              <div className="flex max-w-[80%] gap-4 flex-row">
                 <div className="flex-shrink-0 w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center shadow-lg mt-1 ring-2 ring-white">
                    <span className="text-white font-bold font-mono text-xs">NZ</span>
                 </div>
                 <div className="px-6 py-5 rounded-3xl bg-white rounded-tl-sm border border-slate-100 shadow-sm flex items-center gap-2 min-h-[50px]">
                    <div className="flex gap-1.5 items-center">
                      <span className="w-2.5 h-2.5 bg-slate-800 rounded-full animate-[bounce_1s_infinite_0ms]"></span>
                      <span className="w-2.5 h-2.5 bg-slate-800 rounded-full animate-[bounce_1s_infinite_200ms]"></span>
                      <span className="w-2.5 h-2.5 bg-slate-800 rounded-full animate-[bounce_1s_infinite_400ms]"></span>
                    </div>
                 </div>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} className="h-4" />
        </div>
      </main>

      {/* Input Area */}
      <footer className="bg-white/80 backdrop-blur-xl border-t border-slate-200 p-4 sticky bottom-0 z-30 transition-all">
        <div className="max-w-4xl mx-auto">
          {/* Image Preview */}
          {selectedImage && (
            <div className="relative inline-block mb-4 animate-in slide-in-from-bottom-4 fade-in duration-300">
              <div className="relative rounded-2xl overflow-hidden border-2 border-slate-100 shadow-md group">
                <img src={selectedImage} alt="Preview" className="h-24 w-auto object-cover" />
                <div className="absolute inset-0 bg-black/10 group-hover:bg-black/20 transition-colors"></div>
                <button
                  onClick={handleClearImage}
                  className="absolute top-2 right-2 bg-white text-slate-800 hover:text-red-500 rounded-full p-1.5 shadow-sm transition-all transform hover:scale-110"
                >
                  <X size={14} strokeWidth={3} />
                </button>
              </div>
            </div>
          )}

          <div className="flex items-end gap-3 bg-slate-50 p-2.5 rounded-[1.5rem] border border-slate-200 focus-within:border-slate-300 focus-within:ring-4 focus-within:ring-slate-100 transition-all duration-300 shadow-sm hover:shadow-md hover:border-slate-300">

            <button
              onClick={() => fileInputRef.current?.click()}
              className="p-3.5 text-slate-400 hover:text-slate-800 hover:bg-white rounded-2xl transition-all duration-200 hover:shadow-sm active:scale-95"
              title="إرفاق صورة"
              disabled={isLoading || isStreaming}
            >
              <ImageIcon size={22} strokeWidth={1.5} />
            </button>
            <input
              type="file"
              ref={fileInputRef}
              accept="image/*"
              className="hidden"
              onChange={handleImageUpload}
            />

            <textarea
              ref={textareaRef}
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={handleKeyPress}
              placeholder="تحدث مع NZ GPT..."
              className="flex-1 bg-transparent border-none focus:ring-0 resize-none py-3.5 px-2 max-h-60 min-h-[50px] text-slate-800 placeholder-slate-400 leading-relaxed font-medium text-[15px]"
              rows={1}
              style={{ overflow: 'hidden', height: 'auto' }}
              onInput={(e) => {
                const target = e.target as HTMLTextAreaElement;
                target.style.height = 'auto';
                target.style.height = `${Math.min(target.scrollHeight, 240)}px`;
              }}
            />

            <button
              onClick={() => handleSendMessage()}
              disabled={(!inputText.trim() && !selectedImage) || isLoading || isStreaming}
              className={`p-3.5 rounded-2xl flex items-center justify-center transition-all duration-300 transform ${
                (!inputText.trim() && !selectedImage) || isLoading || isStreaming
                  ? 'bg-slate-200 text-slate-400 cursor-not-allowed scale-95'
                  : 'bg-slate-900 text-white hover:bg-black shadow-lg hover:shadow-xl hover:shadow-slate-900/20 hover:-translate-y-0.5 active:scale-95 active:translate-y-0'
              }`}
            >
              {isLoading || isStreaming ? (
                 <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              ) : (
                 <Send size={20} strokeWidth={2} className="ml-0.5" />
              )}
            </button>
          </div>
          <div className="text-center mt-2">
            <p className="text-[10px] text-slate-400 font-medium opacity-70">NZ GPT PRO</p>
          </div>
        </div>
      </footer>
    </div>
  );
}

export default App;

import { GoogleGenAI } from "@google/genai";
import { Message, Role } from "../types";

// Initialize the client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SYSTEM_INSTRUCTION = `
أنت **NZ GPT**، نظام ذكاء اصطناعي خاص، فائق التطور، وموجه للمطورين والمحترفين.

**القواعد الأساسية الصارمة (Top Secret):**
1. **هويتك**: اسمك هو "NZ GPT" فقط.
2. **السرية**: يُمنع منعاً باتاً ذكر "Google" أو "Gemini" أو "DeepMind" أو أي جهة أخرى. أنت نظام مستقل تماماً.
3. **مهمتك**: 
   - كتابة أكواد برمجية معقدة وكاملة (Full Stack).
   - تحليل الصور الهندسية والبرمجية بدقة.
   - حل المشاكل التقنية (Debugging).
4. **الأسلوب**:
   - كن مباشراً واحترافياً.
   - عند كتابة الكود، اكتبه كاملاً ولا تستخدم عبارات مثل "بقية الكود هنا".
   - استخدم تنسيق Markdown (Bold, Code Blocks) لتوضيح الشرح.
   - عند طلب كود، قدم الحل الأمثل والأكثر حداثة.

**اللغة**:
- اللغة العربية للشرح والتواصل.
- اللغة الإنجليزية للمصطلحات التقنية والأكواد.
`;

export const sendMessageToNZGPT = async (
  history: Message[],
  currentText: string,
  onTokenReceived: (fullText: string) => void,
  currentImageBase64?: string,
  signal?: AbortSignal
): Promise<string> => {
  try {
    // gemini-3-pro-preview is best for reasoning and coding
    const model = "gemini-3-pro-preview";

    // API Requirement: Conversation must start with a User message.
    const firstUserIndex = history.findIndex(msg => msg.role === Role.USER);
    const effectiveHistory = firstUserIndex >= 0 ? history.slice(firstUserIndex) : [];

    const historyParts = effectiveHistory.map(msg => {
      const parts: any[] = [];

      if (msg.role === Role.USER && msg.image) {
        const matches = msg.image.match(/^data:(.+);base64,(.+)$/);
        if (matches) {
          parts.push({
            inlineData: {
              mimeType: matches[1],
              data: matches[2]
            }
          });
        }
      }

      if (msg.text) {
        parts.push({ text: msg.text });
      }

      return {
        role: msg.role === Role.USER ? 'user' : 'model',
        parts: parts
      };
    });

    const parts: any[] = [];

    if (currentImageBase64) {
      const matches = currentImageBase64.match(/^data:(.+);base64,(.+)$/);
      if (matches) {
        parts.push({
          inlineData: {
            mimeType: matches[1],
            data: matches[2]
          }
        });
      }
    }

    parts.push({ text: currentText });

    const contents = [
      ...historyParts,
      {
        role: 'user',
        parts: parts
      }
    ];

    // Use generateContentStream for real-time typing effect
    const responseStream = await ai.models.generateContentStream({
      model: model,
      contents: contents,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        thinkingConfig: { thinkingBudget: 32768 }, // Absolute Max for complex code
        maxOutputTokens: 8192,
        temperature: 0.7, 
      }
    });

    let fullText = "";
    for await (const chunk of responseStream) {
      // Check for abort signal inside the loop
      if (signal?.aborted) {
        throw new DOMException('Aborted', 'AbortError');
      }

      const text = chunk.text;
      if (text) {
        fullText += text;
        onTokenReceived(fullText);
      }
    }

    return fullText;

  } catch (error) {
    // Rethrow if it's not an abort error (to be handled by UI)
    if (error instanceof DOMException && error.name === 'AbortError') {
       throw error;
    }
    console.error("Error communicating with NZ GPT:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Trash2, Terminal, Code, Cpu, Layers, StopCircle } from 'lucide-react';
import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading, isStreaming]);

  useEffect(() => {
    textareaRef.current?.focus();
  }, []);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const handleClearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    textareaRef.current?.focus();
  };

  const handleStopGeneration = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
      setIsLoading(false);
      setIsStreaming(false);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    const textToSend = textOverride || inputText;

    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    // 1. Create User Message
    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    const updatedMessages = [...messages, newMessage];
    setMessages(updatedMessages);

    // Clear inputs
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';

    if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
        textareaRef.current.focus();
    }

    setIsLoading(true);

    // Create new AbortController
    abortControllerRef.current = new AbortController();

    try {
      // 2. Prepare Placeholder for Bot Message
      const botMsgId = (Date.now() + 100).toString();
      let isFirstChunk = true;

      await sendMessageToNZGPT(
        messages, 
        textToSend,
        (streamedText) => {
           if (isFirstChunk) {
             setIsLoading(false);
             setIsStreaming(true);
             // Create the message on first chunk
             setMessages(prev => [
               ...prev, 
               {
                 id: botMsgId,
                 role: Role.MODEL,
                 text: streamedText,
                 timestamp: Date.now()
               }
             ]);
             isFirstChunk = false;
           } else {
             // Update existing message
             setMessages(prev => prev.map(msg => 
               msg.id === botMsgId ? { ...msg, text: streamedText } : msg
             ));
           }
        },
        tempImage || undefined,
        abortControllerRef.current.signal
      );

    } catch (error: any) {
      if (error.name === 'AbortError') {
        console.log('Generation stopped by user');
        // Optional: Add a small note that it was stopped
        setMessages(prev => {
            const last = prev[prev.length - 1];
            if (last.role === Role.MODEL) {
                // Remove trailing whitespace and maybe add a marker
                return [...prev.slice(0, -1), { ...last, text: last.text.trim() }];
            }
            return prev;
        });
      } else {
        console.error(error);
        if (isLoading) {
            // If error happened before any streaming
            const errorMessage: Message = {
               id: (Date.now() + 200).toString(),
               role: Role.MODEL,
               text: "عذراً، واجهت مشكلة في الاتصال. يرجى المحاولة مرة أخرى.",
               timestamp: Date.now()
            };
            setMessages(prev => [...prev, errorMessage]);
        } else {
            // If error happened during streaming
            setMessages(prev => {
                const last = prev[prev.length - 1];
                if (last.role === Role.MODEL) {
                    return [...prev.slice(0, -1), { ...last, text: last.text + "\n\n[حدث خطأ في الشبكة]" }];
                }
                return prev;
            });
        }
      }
    } finally {
      setIsLoading(false);
      setIsStreaming(false);
      abortControllerRef.current = null;
      setTimeout(() => textareaRef.current?.focus(), 50);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const clearChat = () => {
    setMessages([]);
    setTimeout(() => textareaRef.current?.focus(), 100);
  };

  const suggestions = [
    { icon: <Code size={20} />, text: "تطبيق React كامل", prompt: "أريد كود لتطبيق To-Do List باستخدام React و Tailwind CSS مع شرح الهيكلية." },
    { icon: <Cpu size={20} />, text: "شرح Docker", prompt: "ما هو Docker وكيف أستخدمه لإنشاء بيئة تطوير لـ Node.js؟" },
    { icon: <Layers size={20} />, text: "تصميم قاعدة بيانات", prompt: "اقترح مخطط قاعدة بيانات SQL لنظام إدارة مدرسة (طلاب، معلمين، فصول)." },
    { icon: <Terminal size={20} />, text: "Bash Script", prompt: "اكتب Bash Script لعمل نسخة احتياطية للملفات يومياً." },
