const getApiKey = () => {
    // 1. الأولوية للمفتاح الموجود في الكود (للـ APK)
    if (HARDCODED_API_KEY) return HARDCODED_API_KEY;

    // 2. محاولة جلب المفتاح من متغيرات البيئة (للمطورين)
    // نستخدم try-catch وتفحص النوع لتجنب انهيار التطبيق في المتصفح/الهاتف
    try {
        // @ts-ignore
        if (typeof process !== 'undefined' && process.env && process.env.API_KEY) {
            // @ts-ignore
            return process.env.API_KEY;
        }
    } catch (e) {
        // ignore safely
    }

    console.warn("لم يتم العثور على مفتاح API. يرجى إضافته في ملف services/geminiService.ts");
    return ""; 
};

