import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Trash2, Terminal, Code, Cpu, Layers, StopCircle, Sparkles } from 'lucide-react';
import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading, isStreaming]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    const textToSend = textOverride || inputText;
    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);

    setIsLoading(true);
    abortControllerRef.current = new AbortController();

    try {
      const botMsgId = (Date.now() + 100).toString();
      let isFirstChunk = true;

      await sendMessageToNZGPT(
        messages, 
        textToSend,
        (streamedText) => {
           if (isFirstChunk) {
             setIsLoading(false);
             setIsStreaming(true);
             setMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, text: streamedText, timestamp: Date.now() }]);
             isFirstChunk = false;
           } else {
             setMessages(prev => prev.map(msg => msg.id === botMsgId ? { ...msg, text: streamedText } : msg));
           }
        },
        tempImage || undefined,
        abortControllerRef.current.signal
      );
    } catch (error: any) {
      if (error.name !== 'AbortError') {
        setMessages(prev => [...prev, { id: Date.now().toString(), role: Role.MODEL, text: "حدث خطأ في الاتصال، يرجى التحقق من الشبكة.", timestamp: Date.now() }]);
      }
    } finally {
      setIsLoading(false);
      setIsStreaming(false);
      abortControllerRef.current = null;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#0f172a] text-slate-100 overflow-hidden font-sans" dir="rtl">
      {/* Header */}
      <header className="bg-[#1e293b]/80 backdrop-blur-lg border-b border-slate-700/50 px-5 py-4 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/20">
            <span className="text-white font-black text-sm tracking-tighter">NZ</span>
          </div>
          <div>
            <h1 className="text-lg font-bold bg-gradient-to-r from-white to-slate-400 bg-clip-text text-transparent">NZ GPT PRO</h1>
            <div className="flex items-center gap-1.5">
              <span className={`w-2 h-2 rounded-full ${isLoading || isStreaming ? 'bg-blue-500 animate-pulse' : 'bg-emerald-500'}`}></span>
              <span className="text-[10px] font-semibold text-slate-400 uppercase tracking-widest">
                {isLoading ? 'Thinking...' : isStreaming ? 'Typing...' : 'System Ready'}
              </span>
            </div>
          </div>
        </div>
        <button onClick={() => setMessages([])} className="p-2 text-slate-500 hover:text-red-400 transition-colors">
          <Trash2 size={20} />
        </button>
      </header>

      {/* Main Chat */}
      <main className="flex-1 overflow-y-auto p-4 space-y-6">
        {messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center space-y-8 animate-in fade-in duration-1000">
            <div className="p-6 bg-slate-800/50 rounded-3xl border border-slate-700/50 shadow-2xl backdrop-blur-sm">
              <Sparkles size={48} className="text-blue-500 mb-4 mx-auto" />
              <h2 className="text-2xl font-black mb-2">كيف يمكنني مساعدتك اليوم؟</h2>
              <p className="text-slate-400 text-sm max-w-xs mx-auto leading-relaxed">أنا NZ GPT، رفيقك الذكي في رحلتك البرمجية والتقنية.</p>
            </div>

