            <button onClick={() => setMessages([])} className="p-1.5 text-slate-500 hover:text-white transition-colors">
              <Trash2 size={16} />
            </button>
          )}
        </div>
      </header>

      {/* Main Chat Area */}
      <main className="flex-1 overflow-y-auto px-4 py-8">
        <div className="max-w-3xl mx-auto space-y-10">
          {messages.length === 0 ? (
