              <div className="w-16 h-16 bg-white/5 border border-white/10 rounded-2xl flex items-center justify-center mb-6">
                <Sparkles size={32} className="text-white/80" />
              </div>
              <h2 className="text-3xl font-bold text-white mb-4">أهلاً بك في NZ GPT</h2>
              <p className="text-slate-500 text-sm max-w-sm leading-relaxed mb-12">
