              )}
            </div>
          </div>
          <p className="text-[10px] text-center text-slate-600 mt-3 font-medium tracking-tight">
            NZ GPT قد يقدم معلومات غير دقيقة في بعض الأحيان.
          </p>
        </div>
      </footer>
    </div>
  );
}

