import React from 'react';
import { Message, Role } from '../types';
import { ExternalLink, Globe } from 'lucide-react';
import CodeBlock from './CodeBlock';

interface MessageItemProps {
  message: Message;
}

const MessageItem: React.FC<MessageItemProps> = ({ message }) => {
  const isUser = message.role === Role.USER;

  const renderInlineStyles = (text: string) => {
    const parts = text.split(/(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))/g);
    return parts.map((part, index) => {
      if (part.startsWith('`') && part.endsWith('`')) {
        return <code key={index} className="bg-white/10 text-pink-400 px-1.5 py-0.5 rounded text-[13px] font-mono mx-0.5" dir="ltr">{part.slice(1, -1)}</code>;
      }
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={index} className="font-bold text-white">{part.slice(2, -2)}</strong>;
      }
      if (part.startsWith('[') && part.includes('](') && part.endsWith(')')) {
        const match = part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
        if (match) {
          return (
            <a key={index} href={match[2]} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:underline inline-flex items-center gap-0.5 mx-1">
              {match[1]} <ExternalLink size={10} />
            </a>
          );
        }
      }
      return part;
    });
  };

  const renderContent = (fullText: string) => {
    const parts = fullText.split(/(```[\s\S]*?```|```[\s\S]*$)/g);
    return parts.map((part, index) => {
      if (part.startsWith('```')) {
        let content = part.slice(3);
        if (content.endsWith('```')) content = content.slice(0, -3);
        const firstLineBreak = content.indexOf('\n');
        let language = 'code';
        let code = content;
        if (firstLineBreak > -1) {
            const potentialLang = content.substring(0, firstLineBreak).trim();
            if (potentialLang.length < 15 && !potentialLang.includes(' ')) {
                language = potentialLang || 'code';
                code = content.substring(firstLineBreak + 1);
            }
        }
        return <CodeBlock key={index} code={code.trim()} language={language} />;
      }

      if (part.trim() === '') return null;

      return (
        <div key={index} className="space-y-3">
          {part.split('\n').map((line, i) => {
            if (!line.trim()) return <div key={i} className="h-2"></div>;
            if (line.startsWith('### ')) return <h3 key={i} className="text-lg font-bold text-white mt-4 mb-2">{renderInlineStyles(line.replace(/^###\s+/, ''))}</h3>;
            if (line.startsWith('## ')) return <h2 key={i} className="text-xl font-bold text-white mt-6 mb-3">{renderInlineStyles(line.replace(/^##\s+/, ''))}</h2>;
            if (line.match(/^[\-\*]\s/)) return <div key={i} className="flex gap-2 mr-2"><span className="text-slate-500 mt-1.5 text-[8px]">●</span><span className="text-slate-300">{renderInlineStyles(line.replace(/^[\-\*]\s+/, ''))}</span></div>;
            return <p key={i} className="leading-relaxed text-slate-300">{renderInlineStyles(line)}</p>;
          })}
        </div>
      );
    });
  };

  return (
    <div className={`flex w-full animate-in slide-in-from-bottom-3 duration-500 ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div className={`flex gap-4 max-w-[90%] md:max-w-[80%] ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>
        <div className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 mt-1 border ${
          isUser ? 'bg-white border-white text-black' : 'bg-white/5 border-white/10 text-slate-400'
        }`}>
          {isUser ? <span className="text-[10px] font-bold">U</span> : <Globe size={14} />}
        </div>

        <div className={`flex flex-col ${isUser ? 'items-end' : 'items-start'}`}>
          <div className={`px-5 py-4 rounded-[20px] text-[15px] ${
            isUser 
              ? 'bg-white/10 text-white rounded-tr-none' 
              : 'bg-white/[0.03] text-slate-200 border border-white/5 rounded-tl-none shadow-xl'
          }`}>
            {message.image && (
              <img src={message.image} alt="Upload" className="rounded-xl mb-4 max-w-full border border-white/10" />
            )}
            <div>
              {isUser ? <p className="whitespace-pre-wrap leading-relaxed">{message.text}</p> : renderContent(message.text)}
            </div>
          </div>
          <span className="text-[9px] text-slate-600 mt-2 font-bold uppercase tracking-widest px-1">
            {new Date(message.timestamp).toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
      </div>
    </div>
  );
};

