import React from 'react';
import { Message, Role } from '../types';
import { ExternalLink, Sparkles, User } from 'lucide-react';
import CodeBlock from './CodeBlock';

interface MessageItemProps {
  message: Message;
}

const MessageItem: React.FC<MessageItemProps> = ({ message }) => {
  const isUser = message.role === Role.USER;

  const renderInlineStyles = (text: string) => {
    const parts = text.split(/(`[^`]+`|\*\*[^*]+\*\*|\[[^\]]+\]\([^)]+\))/g);
    return parts.map((part, index) => {
      if (part.startsWith('`') && part.endsWith('`')) {
        return <code key={index} className="bg-white/10 text-slate-200 px-1.5 py-0.5 rounded text-[13px] font-mono mx-0.5" dir="ltr">{part.slice(1, -1)}</code>;
      }
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={index} className="font-bold text-white">{part.slice(2, -2)}</strong>;
      }
      if (part.startsWith('[') && part.includes('](') && part.endsWith(')')) {
        const match = part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
        if (match) {
          return (
            <a key={index} href={match[2]} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:underline inline-flex items-center gap-0.5 mx-1">
              {match[1]} <ExternalLink size={10} />
            </a>
          );
        }
      }
      return part;
    });
  };

  const renderContent = (fullText: string) => {
    const parts = fullText.split(/(```[\s\S]*?```|```[\s\S]*$)/g);
    return parts.map((part, index) => {
      if (part.startsWith('```')) {
        let content = part.slice(3);
        if (content.endsWith('```')) content = content.slice(0, -3);
        const firstLineBreak = content.indexOf('\n');
        let language = 'code';
        let code = content;
        if (firstLineBreak > -1) {
            const potentialLang = content.substring(0, firstLineBreak).trim();
            if (potentialLang.length < 15 && !potentialLang.includes(' ')) {
                language = potentialLang || 'code';
                code = content.substring(firstLineBreak + 1);
            }
        }
        return <CodeBlock key={index} code={code.trim()} language={language} />;
      }

      if (part.trim() === '') return null;

      return (
        <div key={index} className="space-y-4">
          {part.split('\n').map((line, i) => {
            if (!line.trim()) return <div key={i} className="h-4"></div>;
            if (line.startsWith('### ')) return <h3 key={i} className="text-lg font-bold text-white mt-6 mb-2">{renderInlineStyles(line.replace(/^###\s+/, ''))}</h3>;
            if (line.startsWith('## ')) return <h2 key={i} className="text-xl font-bold text-white mt-8 mb-4">{renderInlineStyles(line.replace(/^##\s+/, ''))}</h2>;
            if (line.match(/^[\-\*]\s/)) return <div key={i} className="flex gap-3 mr-1"><span className="text-slate-500 mt-2 text-[6px]">●</span><span className="text-slate-300 flex-1">{renderInlineStyles(line.replace(/^[\-\*]\s+/, ''))}</span></div>;
            if (line.match(/^\d+\.\s/)) return <div key={i} className="flex gap-3 mr-1"><span className="text-slate-500 font-mono text-xs mt-1">{line.match(/^\d+/)?.[0]}.</span><span className="text-slate-300 flex-1">{renderInlineStyles(line.replace(/^\d+\.\s+/, ''))}</span></div>;
            return <p key={i} className="leading-relaxed text-[#d1d1d1]">{renderInlineStyles(line)}</p>;
          })}
        </div>
      );
    });
  };

  return (
    <div className={`group w-full py-8 px-4 md:px-6 border-b border-white/5 animate-in fade-in duration-500 ${isUser ? '' : 'bg-transparent'}`}>
      <div className="max-w-3xl mx-auto flex gap-4 md:gap-6">

        {/* Avatar */}
        <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 mt-0.5 border ${
          isUser ? 'bg-slate-700 border-white/10 text-white' : 'bg-emerald-600 border-emerald-500/20 text-white shadow-lg'
        }`}>
          {isUser ? <User size={16} /> : <Sparkles size={16} fill="currentColor" />}
        </div>

        {/* Text Area */}
        <div className="flex-1 overflow-hidden">
          <p className="text-[11px] font-bold uppercase tracking-widest text-slate-500 mb-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
            {isUser ? 'You' : 'NZ GPT'}
          </p>

          <div className="text-[15px] selection:bg-slate-700">
            {message.image && (
              <img src={message.image} alt="Upload" className="rounded-xl mb-4 max-w-sm w-full border border-white/10 shadow-2xl" />
            )}

            {isUser ? (
              <p className="whitespace-pre-wrap leading-relaxed text-slate-200">{message.text}</p>
            ) : (
              <div className="prose prose-invert max-w-none">
                {renderContent(message.text)}
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

