import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, Trash2, WifiOff, StopCircle, Sparkles, Menu, Plus, MessageSquare, User, ChevronRight } from 'lucide-react';
import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isLoading, isStreaming]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        if (textareaRef.current) {
          textareaRef.current.focus();
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    if (!isOnline) return;
    const textToSend = textOverride || inputText;
    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);

    setIsLoading(true);
    abortControllerRef.current = new AbortController();

    try {
      const botMsgId = (Date.now() + 100).toString();
      let isFirstChunk = true;

      await sendMessageToNZGPT(
        messages, 
        textToSend,
        (streamedText) => {
           if (isFirstChunk) {
             setIsLoading(false);
             setIsStreaming(true);
             setMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, text: streamedText, timestamp: Date.now() }]);
             isFirstChunk = false;
           } else {
             setMessages(prev => prev.map(msg => msg.id === botMsgId ? { ...msg, text: streamedText } : msg));
           }
        },
        tempImage || undefined,
        abortControllerRef.current.signal
      );
    } catch (error: any) {
      if (error.name !== 'AbortError') {
        setMessages(prev => [...prev, { id: Date.now().toString(), role: Role.MODEL, text: "حدث خطأ. يرجى التأكد من اتصالك.", timestamp: Date.now() }]);
      }
    } finally {
      setIsLoading(false);
      setIsStreaming(false);
      abortControllerRef.current = null;
    }
  };

  if (!isOnline) {
    return (
      <div className="flex flex-col items-center justify-center h-full bg-[#212121] text-white p-6 text-center">
        <WifiOff size={48} className="text-gray-500 mb-4" />
        <h1 className="text-xl font-bold mb-2">لا يوجد اتصال بالإنترنت</h1>
        <p className="text-gray-400 text-sm mb-6">يرجى الاتصال بالشبكة للمتابعة.</p>
        <button onClick={() => window.location.reload()} className="px-6 py-2 bg-white text-black rounded-full font-bold">تحديث الصفحة</button>
      </div>
    );
  }

  return (
    <div className="flex h-full bg-[#212121] text-gray-100 overflow-hidden font-sans" dir="rtl">

      {/* Sidebar Overlay */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40 md:hidden backdrop-blur-sm"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed md:relative right-0 top-0 bottom-0 z-50
        w-[280px] bg-[#171717] transition-transform duration-300 ease-in-out
        ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
        flex flex-col border-l border-white/5 shadow-2xl
      `}>
        <div className="p-4">
          <button 
            onClick={() => { setMessages([]); setIsSidebarOpen(false); }}
            className="w-full flex items-center justify-between p-3 rounded-lg hover:bg-[#2f2f2f] transition-all border border-white/10 group"
          >
            <div className="flex items-center gap-3">
              <Plus size={18} className="text-gray-300" />
              <span className="text-sm font-medium">محادثة جديدة</span>
            </div>
            <MessageSquare size={16} className="text-gray-500" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-2 space-y-1">
          <p className="text-[11px] font-bold text-gray-500 px-2 py-2 uppercase tracking-widest">تاريخ المحادثات</p>
          {messages.length > 0 ? (
            <div className="p-3 rounded-lg bg-[#2f2f2f] text-sm truncate text-gray-300 border-r-4 border-white">
              {messages[0].text}
            </div>
          ) : (
            <p className="text-xs text-gray-600 px-2">لا توجد محادثات سابقة</p>
          )}
        </div>

        <div className="p-4 border-t border-white/5">
           <div className="flex items-center gap-3 p-3 rounded-xl hover:bg-[#2f2f2f] cursor-pointer transition-colors bg-[#1e1e1e]">
              <div className="w-9 h-9 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-lg flex items-center justify-center text-xs font-bold text-white shadow-lg">NZ</div>
              <div className="flex-1 truncate">
                 <p className="text-sm font-semibold">مستخدم NZ PRO</p>
                 <p className="text-[10px] text-gray-500 uppercase">الخطة الاحترافية</p>
              </div>
           </div>
        </div>
      </aside>

      {/* Main Container */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#212121] relative h-full">

        {/* Navbar */}
        <header className="h-14 flex items-center justify-between px-4 bg-[#212121]/90 backdrop-blur-md sticky top-0 z-30">
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 hover:bg-white/5 rounded-lg md:hidden">
            <Menu size={20} />
          </button>

          <div className="flex items-center gap-2">
             <span className="font-bold text-lg tracking-tight">NZ GPT</span>
             <span className="bg-white/10 text-[9px] px-1.5 py-0.5 rounded-md font-black text-gray-400">PRO</span>
          </div>

          <div className="w-10 flex justify-end">
            {messages.length > 0 && (
              <button onClick={() => setMessages([])} className="p-2 text-gray-500 hover:text-white transition-colors">
                <Plus size={20} />
              </button>
            )}
          </div>
        </header>

        {/* Chat List */}
        <main className="flex-1 overflow-y-auto">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center p-6 text-center">
               <div className="w-16 h-16 mb-6 bg-white/5 rounded-2xl flex items-center justify-center text-white/20">
                  <Sparkles size={40} />
               </div>
               <h2 className="text-2xl font-bold text-white mb-3">كيف يمكنني مساعدتك؟</h2>
               <div className="grid grid-cols-1 gap-2 w-full max-w-sm mt-8">
                  {["اكتب كود Python لفرز قائمة", "اشرح ميكانيكا الكم ببساطة", "حلل لي هذه الصورة"].map((hint, i) => (
                    <button key={i} onClick={() => handleSendMessage(hint)} className="p-3 text-sm bg-white/5 border border-white/10 rounded-xl hover:bg-white/10 text-right transition-colors truncate">
                      {hint}
                    </button>
                  ))}
               </div>
            </div>
          ) : (
            <div className="w-full">
              {messages.map(msg => <MessageItem key={msg.id} message={msg} />)}
              {isLoading && (
                <div className="py-8 px-4 md:px-6">
