                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} className="h-40" />
            </div>
          )}
        </main>

        {/* Input Bar */}
        <div className="sticky bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-[#212121] via-[#212121] to-transparent pointer-events-none">
          <div className="max-w-3xl mx-auto pointer-events-auto">

