            <a key={index} href={match[2]} target="_blank" rel="noopener noreferrer" className="text-blue-400 hover:underline inline-flex items-center gap-0.5 mx-1">
              {match[1]} <ExternalLink size={10} />
            </a>
          );
        }
      }
      return part;
    });
  };

  const renderContent = (fullText: string) => {
    const parts = fullText.split(/(```[\s\S]*?```|```[\s\S]*$)/g);
    return parts.map((part, index) => {
      if (part.startsWith('```')) {
        let content = part.slice(3);
        if (content.endsWith('```')) content = content.slice(0, -3);
        const firstLineBreak = content.indexOf('\n');
        let language = 'code';
        let code = content;
        if (firstLineBreak > -1) {
            const potentialLang = content.substring(0, firstLineBreak).trim();
            if (potentialLang.length < 15 && !potentialLang.includes(' ')) {
                language = potentialLang || 'code';
                code = content.substring(firstLineBreak + 1);
            }
        }
        return <CodeBlock key={index} code={code.trim()} language={language} />;
      }

      if (part.trim() === '') return null;

      return (
        <div key={index} className="space-y-4">
          {part.split('\n').map((line, i) => {
            if (!line.trim()) return <div key={i} className="h-3"></div>;
            if (line.startsWith('### ')) return <h3 key={i} className="text-lg font-bold text-white mt-6 mb-2 leading-tight">{renderInlineStyles(line.replace(/^###\s+/, ''))}</h3>;
            if (line.startsWith('## ')) return <h2 key={i} className="text-xl font-bold text-white mt-8 mb-4 leading-tight">{renderInlineStyles(line.replace(/^##\s+/, ''))}</h2>;
            if (line.match(/^[\-\*]\s/)) return <div key={i} className="flex gap-3 pr-2"><span className="text-gray-500 mt-2 text-[6px]">●</span><span className="text-gray-300 flex-1 leading-relaxed">{renderInlineStyles(line.replace(/^[\-\*]\s+/, ''))}</span></div>;
            if (line.match(/^\d+\.\s/)) return <div key={i} className="flex gap-3 pr-1 font-medium"><span className="text-gray-500 font-mono text-sm mt-0.5">{line.match(/^\d+/)?.[0]}.</span><span className="text-gray-300 flex-1 leading-relaxed">{renderInlineStyles(line.replace(/^\d+\.\s+/, ''))}</span></div>;
            return <p key={i} className="leading-relaxed text-[#ececec]">{renderInlineStyles(line)}</p>;
          })}
        </div>
      );
    });
  };

  return (
    <div className={`w-full py-8 px-4 md:px-6 border-b border-white/5 animate-in fade-in duration-300`}>
      <div className="max-w-3xl mx-auto flex gap-4 md:gap-6 items-start">

        {/* Avatar */}
        <div className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 border shadow-sm ${
          isUser ? 'bg-[#3f3f3f] border-white/10 text-white' : 'bg-emerald-600 border-emerald-500/20 text-white'
        }`}>
          {isUser ? <User size={18} /> : <Sparkles size={18} fill="currentColor" />}
        </div>

        {/* Text Area */}
        <div className="flex-1 min-w-0 pt-1">
          <p className="text-[10px] font-black uppercase tracking-widest text-gray-500 mb-2">
            {isUser ? 'أنت' : 'NZ GPT'}
