import React, { useState, useRef, useEffect } from 'react';
import { Send, Image as ImageIcon, X, WifiOff, StopCircle, Sparkles, Menu, Plus, MessageSquare, User, ChevronRight } from 'lucide-react';
import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    // التمرير التلقائي للأسفل عند وصول رسائل جديدة
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isLoading]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    if (!isOnline) return;
    const textToSend = textOverride || inputText;
    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);

    setIsLoading(true);
    abortControllerRef.current = new AbortController();

    try {
      const botMsgId = (Date.now() + 100).toString();
      let isFirstChunk = true;

      await sendMessageToNZGPT(
        messages, 
        textToSend,
        (streamedText) => {
           if (isFirstChunk) {
             setIsLoading(false);
             setIsStreaming(true);
             setMessages(prev => [...prev, { id: botMsgId, role: Role.MODEL, text: streamedText, timestamp: Date.now() }]);
             isFirstChunk = false;
           } else {
             setMessages(prev => prev.map(msg => msg.id === botMsgId ? { ...msg, text: streamedText } : msg));
           }
        },
        tempImage || undefined,
        abortControllerRef.current.signal
      );
    } catch (error: any) {
      if (error.name !== 'AbortError') {
        setMessages(prev => [...prev, { id: Date.now().toString(), role: Role.MODEL, text: "حدث خطأ في الاتصال. حاول مرة أخرى.", timestamp: Date.now() }]);
      }
    } finally {
      setIsLoading(false);
      setIsStreaming(false);
      abortControllerRef.current = null;
    }
  };

  if (!isOnline) {
    return (
      <div className="flex flex-col items-center justify-center h-full bg-[#212121] text-white p-10 text-center">
        <WifiOff size={60} className="text-gray-600 mb-6" />
        <h1 className="text-2xl font-bold mb-3">لا يتوفر اتصال</h1>
        <p className="text-gray-400 mb-8 leading-relaxed">تطبيق NZ GPT يتطلب اتصالاً بالإنترنت لتقديم إجابات ذكية.</p>
        <button onClick={() => window.location.reload()} className="w-full max-w-xs py-4 bg-white text-black rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-transform">إعادة المحاولة</button>
      </div>
    );
  }

  return (
    <div className="flex h-full w-full bg-[#212121] text-gray-100 overflow-hidden relative">

      {/* Sidebar - Mobile Overlay */}
      <div className={`fixed inset-0 bg-black/70 z-[60] transition-opacity duration-300 md:hidden ${isSidebarOpen ? 'opacity-100 visible' : 'opacity-0 invisible'}`} onClick={() => setIsSidebarOpen(false)} />

      {/* Sidebar Content */}
      <aside className={`fixed md:relative top-0 right-0 h-full w-[280px] bg-[#171717] z-[70] border-l border-white/5 transition-transform duration-300 ease-in-out flex flex-col ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
        <div className="p-4 border-b border-white/5">
          <button onClick={() => { setMessages([]); setIsSidebarOpen(false); }} className="w-full flex items-center gap-3 p-3 rounded-xl border border-white/10 hover:bg-white/5 transition-colors group">
            <Plus size={18} />
            <span className="text-sm font-bold">محادثة جديدة</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2">
          <p className="text-[10px] font-black text-gray-500 uppercase tracking-[2px] mb-4">المحادثات</p>
          {messages.length > 0 && (
            <div className="p-3 bg-white/5 rounded-xl border-r-2 border-white text-sm truncate text-gray-300">
              {messages[0].text}
            </div>
          )}
        </div>

        <div className="p-4 border-t border-white/5">
           <div className="flex items-center gap-3 p-3 rounded-2xl bg-[#1e1e1e]">
              <div className="w-10 h-10 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-xl flex items-center justify-center font-black shadow-lg">NZ</div>
              <div className="flex-1 min-w-0">
                 <p className="text-sm font-bold truncate">NZ GPT PRO</p>
                 <p className="text-[10px] text-gray-500">الحساب المطور</p>
              </div>
           </div>
        </div>
      </aside>

      {/* Main Viewport */}
      <div className="flex-1 flex flex-col min-w-0 relative">

        {/* Navigation Bar */}
        <header className="h-14 flex items-center justify-between px-4 bg-[#212121]/95 backdrop-blur-sm z-50 border-b border-white/5 shrink-0">
          <div className="flex items-center gap-3">
            <button onClick={() => setIsSidebarOpen(true)} className="p-2 -mr-2 hover:bg-white/5 rounded-xl md:hidden">
              <Menu size={22} />
            </button>
            <div className="flex items-center gap-2">
              <h1 className="font-black text-lg tracking-tight">NZ GPT</h1>
              <span className="bg-white/10 text-[9px] px-1.5 py-0.5 rounded-md font-black text-gray-400">PRO</span>
            </div>
          </div>

          <button onClick={() => setMessages([])} className="p-2 text-gray-500 hover:text-white transition-colors">
            <Plus size={22} />
          </button>
        </header>

        {/* Message Container */}
        <main className="flex-1 overflow-y-auto scroll-smooth">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-500">
               <div className="w-20 h-20 mb-8 bg-white/5 rounded-[28px] flex items-center justify-center text-white/10">
                  <Sparkles size={48} />
               </div>
               <h2 className="text-2xl font-black text-white mb-3">أهلاً بك في NZ GPT</h2>
               <p className="text-gray-500 text-sm max-w-xs leading-relaxed">أنا رفيقك الذكي المطور. كيف يمكنني مساعدتك في أبحاثك أو أكوادك اليوم؟</p>

               <div className="grid grid-cols-1 gap-3 w-full max-w-md mt-12">
                  <button onClick={() => handleSendMessage("ساعدني في حل مشكلة برمجية")} className="p-4 text-sm bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 text-right transition-all">💡 ساعدني في حل مشكلة برمجية</button>
                  <button onClick={() => handleSendMessage("اشرح لي مفهوماً معقداً")} className="p-4 text-sm bg-white/5 border border-white/10 rounded-2xl hover:bg-white/10 text-right transition-all">📚 اشرح لي مفهوماً معقداً</button>
               </div>
            </div>
          ) : (
            <div className="w-full">
              {messages.map(msg => <MessageItem key={msg.id} message={msg} />)}
              {isLoading && (
                <div className="py-10 px-4 md:px-6">
                  <div className="max-w-3xl mx-auto flex gap-4 md:gap-6 items-start">
                    <div className="w-9 h-9 rounded-xl bg-emerald-600 flex items-center justify-center shrink-0 shadow-lg">
                      <Sparkles size={18} className="text-white" />
                    </div>
                    <div className="flex gap-1.5 mt-4">
                      <div className="w-2 h-2 bg-gray-600 rounded-full animate-bounce"></div>
                      <div className="w-2 h-2 bg-gray-600 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                      <div className="w-2 h-2 bg-gray-600 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} className="h-40" />
            </div>
          )}
        </main>

        {/* Floating Input Area */}
        <div className="p-4 bg-gradient-to-t from-[#212121] via-[#212121] to-transparent shrink-0">
          <div className="max-w-3xl mx-auto relative">

            {selectedImage && (
              <div className="absolute -top-24 right-0 p-2 bg-[#2f2f2f] rounded-2xl border border-white/10 shadow-2xl animate-in slide-in-from-bottom-2">
                <img src={selectedImage} className="h-16 w-16 object-cover rounded-lg" />
                <button onClick={() => setSelectedImage(null)} className="absolute -top-2 -left-2 bg-white text-black rounded-full p-1 shadow-lg border border-black/10"><X size={10} /></button>
              </div>
            )}

            <div className="bg-[#2f2f2f] border border-white/10 rounded-[32px] shadow-2xl p-2 flex items-end gap-1 focus-within:border-white/20 transition-all">
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-3 text-gray-400 hover:text-white transition-colors rounded-full active:bg-white/5"
              >
                <ImageIcon size={22} />
              </button>
              <input type="file" ref={fileInputRef} accept="image/*" onChange={handleImageUpload} />

              <textarea 
                ref={textareaRef}
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSendMessage())}
                placeholder="اسأل NZ GPT PRO..."
                className="flex-1 bg-transparent border-none focus:ring-0 text-[16px] py-3 px-2 resize-none h-[54px] max-h-48 text-white placeholder-gray-500"
                rows={1}
                onInput={(e) => {
                  const target = e.target as HTMLTextAreaElement;
                  target.style.height = 'auto';
                  target.style.height = `${target.scrollHeight}px`;
                }}
              />

              <div className="p-1">
                {isLoading || isStreaming ? (
                  <button onClick={() => abortControllerRef.current?.abort()} className="p-3 bg-white text-black rounded-full hover:bg-gray-200 shadow-lg">
                    <StopCircle size={20} />
                  </button>
                ) : (
                  <button 
                    onClick={() => handleSendMessage()}
                    disabled={!inputText.trim() && !selectedImage}
                    className={`p-3 rounded-full transition-all ${(!inputText.trim() && !selectedImage) ? 'text-gray-700 bg-transparent' : 'bg-white text-black shadow-xl hover:scale-105 active:scale-95'}`}
