                  target.style.height = `${Math.min(target.scrollHeight, 180)}px`;
                }}
              />

              <div className="p-1 shrink-0">
                {isLoading || isStreaming ? (
                  <button onClick={() => abortControllerRef.current?.abort()} className="p-3.5 bg-white text-black rounded-full hover:bg-gray-100 shadow-xl active:scale-90 transition-all">
                    <StopCircle size={22} />
                  </button>
                ) : (
                  <button 
                    onClick={() => handleSendMessage()}
