  const handleClearChat = () => {
    if (messages.length > 0 && window.confirm("هل تريد بدء محادثة جديدة؟ سيتم مسح النصوص الحالية.")) {
      setMessages([]);
      setMsgCount(0); // تصفير عداد الرسائل عند بدء محادثة جديدة
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    if (!isOnline) return;
    const textToSend = textOverride || inputText;
    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    // تحديث عداد الرسائل
    const newCount = msgCount + 1;
    setMsgCount(newCount);

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);

    // التحقق من شرط الإعلان (كل رسالتين)
    // الإعلان سيظهر للمستخدم ويتم تحميله من جديد في كل مرة تفتح فيها النافذة
    if (newCount > 0 && newCount % 2 === 0) {
