          )}
        </main>

        <div className="p-6 bg-gradient-to-t from-[#212121] via-[#212121]/95 to-transparent absolute bottom-[50px] left-0 right-0 z-50">
          <div className="max-w-3xl mx-auto safe-pb px-2">

            {selectedImage && (
