// مكون بسيط جداً لعرض الإعلان فقط بدون أي نصوص أو خلفيات سوداء
const AdDirectOverlay = ({ onClose }: { onClose: () => void }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    containerRef.current.innerHTML = '';

    const iframe = document.createElement('iframe');
    // إعطاء صلاحيات كاملة للـ iframe لضمان عمل سكربتات الإعلانات
    iframe.setAttribute('sandbox', 'allow-scripts allow-popups allow-same-origin allow-forms allow-top-navigation allow-presentation');
    iframe.style.width = '320px';
    iframe.style.height = '50px';
    iframe.style.border = 'none';
    iframe.style.overflow = 'hidden';

    containerRef.current.appendChild(iframe);

    const doc = iframe.contentWindow?.document;
    if (doc) {
      doc.open();
      // خلفية شفافة تماماً
      doc.write(`
        <!DOCTYPE html>
        <html>
          <head>
            <style>
              body { margin: 0; padding: 0; display: flex; justify-content: center; align-items: center; background-color: transparent; }
            </style>
          </head>
          <body>
            <script type="text/javascript">
              atOptions = {
                'key' : '28491250',
                'format' : 'iframe',
                'height' : 50,
                'width' : 320,
                'params' : {}
              };
            </script>
            <script type="text/javascript" src="//www.highperformanceformat.com/28491250/invoke.js"></script>
          </body>
        </html>
      `);
      doc.close();
    }
  }, []);

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-[2px] animate-in fade-in duration-200">
      {/* حاوية شفافة تماماً للإعلان */}
      <div className="relative">

        {/* زر إغلاق عائم وواضح */}
        <button 
          onClick={onClose} 
          className="absolute -top-8 left-1/2 -translate-x-1/2 bg-white/10 hover:bg-white/20 text-white rounded-full p-2 backdrop-blur-md transition-all border border-white/10"
        >
          <X size={20} />
        </button>

        {/* منطقة الإعلان - ستكون شفافة إذا لم يظهر الإعلان */}
        <div ref={containerRef} className="flex items-center justify-center"></div>

      </div>
    </div>
  );
};

