import React, { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, X, WifiOff, StopCircle, Sparkles, Trash2 } from 'lucide-react';
import { Message, Role } from './types';
import { sendMessageToNZGPT } from './services/geminiService';
import MessageItem from './components/MessageItem';

// مكون مخفي تماماً لتشغيل كود Popunder (28491250)
// يعمل في الخلفية لمحاولة فتح الإعلان دون عرض إطار أسود فارغ داخل التطبيق
const HiddenPopunderTrigger = ({ onComplete }: { onComplete: () => void }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!containerRef.current) return;

    containerRef.current.innerHTML = '';

    const iframe = document.createElement('iframe');
    // إعطاء صلاحيات كاملة، خاصة allow-popups
    iframe.setAttribute('sandbox', 'allow-scripts allow-popups allow-same-origin allow-forms allow-top-navigation allow-presentation');

    // إخفاء الـ iframe تماماً حتى لا يظهر كصندوق أسود
    iframe.style.width = '1px';
    iframe.style.height = '1px';
    iframe.style.border = 'none';
    iframe.style.position = 'absolute';
    iframe.style.opacity = '0';
    iframe.style.pointerEvents = 'none';

    containerRef.current.appendChild(iframe);

    const doc = iframe.contentWindow?.document;
    if (doc) {
      doc.open();
      // حقن كود Popunder - سيحاول السكربت فتح نافذة جديدة
      doc.write(`
        <!DOCTYPE html>
        <html>
          <body style="margin:0;padding:0;background:transparent;">
            <script type="text/javascript">
              atOptions = {
                'key' : '28491250',
                'format' : 'iframe',
                'height' : 50,
                'width' : 320,
                'params' : {}
              };
            </script>
            <script type="text/javascript" src="//www.highperformanceformat.com/28491250/invoke.js"></script>
          </body>
        </html>
      `);
      doc.close();
    }

    // إزالة المكون بعد 5 ثواني لإعادة تعيين الدورة
    const timer = setTimeout(() => {
      onComplete();
    }, 5000);

    return () => clearTimeout(timer);
  }, [onComplete]);

  // حاوية مخفية خارج نطاق الرؤية
  return <div ref={containerRef} style={{ position: 'fixed', top: '-9999px', left: '-9999px', visibility: 'hidden' }} />;
};

function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // State للإعلان
  const [msgCount, setMsgCount] = useState(0);
  const [triggerPopunder, setTriggerPopunder] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const abortControllerRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isLoading]);

  const handleClearChat = () => {
    if (messages.length > 0 && window.confirm("هل تريد بدء محادثة جديدة؟ سيتم مسح النصوص الحالية.")) {
      setMessages([]);
      setMsgCount(0);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        textareaRef.current?.focus();
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSendMessage = async (textOverride?: string) => {
    if (!isOnline) return;
    const textToSend = textOverride || inputText;
    if ((!textToSend.trim() && !selectedImage) || isLoading || isStreaming) return;

    // تحديث عداد الرسائل
    const newCount = msgCount + 1;
    setMsgCount(newCount);

    const newMessage: Message = {
      id: Date.now().toString(),
      role: Role.USER,
      text: textToSend,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    const tempImage = selectedImage;
    setSelectedImage(null);

